import {createLifecycleService} from '../../server/lifecycle/service.mjs';
import {appendFileSync} from 'node:fs';import path from 'node:path';
const app=await createLifecycleService({dataDir:process.argv[2],masterKey:Buffer.alloc(32,18).toString('base64'),clock:()=>Date.parse('2026-10-14T12:00:00Z'),workerIntervalMs:50,browserVerifier:{verifyPublished:async()=>({state:'unknown',scope:'public-snapshot',viewports:[]})},client:{checkPage:async()=>{appendFileSync(path.join(process.argv[2],'calls.txt'),'check\n');process.send({checked:true});return [{kind:'public',state:'ok',evidence:'Controlled test response'}];},checkSite:async()=>({state:'ok'})}});
if(!app.store.listProjects().length){const project=app.store.createProject({name:'Process proof'});const site=app.store.createSite(project.id,{name:'Fixture',baseUrl:'https://example.com'});app.store.createPage(project.id,{title:'Page',siteId:site.id,fullUrl:'https://example.com/page'});}
process.on('message',async m=>{if(m==='check'){const p=app.store.listProjects()[0],page=app.store.listPages(p.id)[0];await app.handle(new Request('http://localhost:4317/api/lifecycle/pages/'+page.id+'/check',{method:'POST',headers:{Origin:'http://localhost:4317','X-PagePoster-Request':'1','Content-Type':'application/json'},body:'{}'}));}if(m==='state'){const p=app.store.listProjects()[0],page=app.store.listPages(p.id)[0];process.send({checks:app.store.listChecks(page.id).filter(c=>c.kind==='public').length,jobs:app.store.listJobs(p.id).length});}if(m==='stop'){await app.close();process.exit(0);}});app.start();process.send({ready:true});
